import json

def hanoi(n, src, dst, aux):
    if n == 0:
        return []
    return hanoi(n-1, src, aux, dst) + [[n, src, dst]] + hanoi(n-1, aux, dst, src)

moves = hanoi(8, 0, 2, 1)
chunks = [moves[i:i+25] for i in range(0, len(moves), 25)]
for chunk in chunks:
    print(json.dumps(chunk))
